def main():
    input = sys.stdin.readline
    n, k = map(int, input().split())
    time = 240 - k
    ans = 0
    start = 1
    end = 240
    while start <= end:
        middle = (start + end) // 2
        sum = 5 * middle * (middle + 1) // 2
        if time >= sum:
            start = middle + 1
            ans = start
        else:
            end = middle - 1
    if ans > n:
        ans = n + 1
    if ans <= 0:
        ans = 1
    sys.stdout.write(str(ans - 1) + '\n')

